clearScene();setBig(null);
setEq("$$V(\\theta)=\\mathbb{E}\\big[\\textstyle\\sum_t r_t \\mid \\pi_\\theta\\big]$$","top");
note("能评估，但求不了导",640,310,"y lg");
setCap("目标已经清楚了：<b>找一组 θ 让 V(θ) 最大</b>。先看不用梯度怎么办。");

clearScene();setEq(null);
setBig("CMA-ES 保证全局最优","讲座原话 —— 而这句是错的");
setCap("它是<b>无导数的随机局部搜索</b>，经验上很强，但<b>不是</b>全局优化器。");

clearScene();setBig(null);setEq(null);
note("只要能评估 V(θ)",640,280,"g lg");
note("不需要知道任何结构",640,350,"g lg");
setCap("无梯度方法的优点很实在：<b>把整个系统当黑箱</b>就行。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:760,vals:[13,101],
  x:380,y:430,w:520,h:170,max:110,
  label:function(i){return ["d=12（AIBO）","d=100"][i];},
  cls:function(i){return i===1?"r":"v";},
  fmt:function(v){return String(v);}});
note("每次梯度要评估几次",640,466,"y");
setCap("有限差分：每个参数扰动一次，<b>一次梯度要 d+1 次评估</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"无梯度",sub:"黑箱即可 · 局部搜索",state:"on"},
  {label:"有限差分",sub:"每次梯度 d+1 评估",state:"on"},
  {label:"解析梯度",sub:"一次采样得整个梯度",state:"on"}]});
note("参数一多就只剩最后一条",640,420,"y");
setCap("<b>指名反驳</b>：CMA-ES 不保证全局最优。三条路各有适用区间。");

clearScene();setBig(null);
setEq("$$V(\\theta)=\\sum_{\\tau}P(\\tau;\\theta)\\,R(\\tau) \\ \\Longrightarrow\\ \\nabla_\\theta V=\\sum_{\\tau}\\nabla_\\theta P(\\tau;\\theta)\\,R(\\tau)$$","top");
note("R(τ) 与 θ 无关",640,300,"g lg");
note("∇P 才是麻烦",640,360,"r lg");
setCap("把目标写成对<b>轨迹</b>求和：θ 只出现在 <b>P(τ;θ)</b> 里。");

clearScene();setEq(null);
setBig("那得知道转移概率","P(τ;θ) 里明明写着环境");
setCap("这个担心很合理 —— <b>而答案是：一次乘除就把它清掉了</b>。");

clearScene();setBig(null);
setEq("$$\\nabla P=P\\cdot\\frac{\\nabla P}{P}=P\\cdot\\nabla\\log P$$","top");
note("乘除同一个 P",640,300,"y lg");
note("纯恒等变形",640,360,"g lg");
setCap("<b>似然比技巧</b>：∇P = P·∇log P。什么都没假设，只是<b>乘 1</b>。");

clearScene();setBig(null);
setEq("$$\\nabla_\\theta V=\\sum_\\tau P(\\tau;\\theta)\\,\\nabla_\\theta\\log P(\\tau;\\theta)\\,R(\\tau)=\\mathbb{E}_\\tau\\big[\\nabla_\\theta\\log P\\cdot R\\big]$$","top");
note("求和变成期望",640,300,"g lg");
note("期望可以采样估",640,360,"y lg");
setCap("代回去：<b>对轨迹的求和变成了一个期望</b> —— 而期望可以用采样估。");

clearScene();setBig(null);setEq(null);
note("没有近似",400,290,"g lg");
note("没有假设",880,290,"g lg");
note("只是乘了个 1",640,400,"y lg");
setCap("<b>指名反驳</b>：这一步<b>不是近似</b> —— 是恒等变形，把求和变成了期望。");

clearScene();setBig(null);
setEq("$$P(\\tau;\\theta)=\\mu(s_0)\\prod_{t}P(s_{t+1}\\mid s_t,a_t)\\,\\pi_\\theta(a_t\\mid s_t)$$","top");
note("三样东西相乘",640,300,"b lg");
note("取 log 就变成相加",640,360,"y lg");
setCap("轨迹概率是三项的<b>乘积</b>：初始分布 × 转移 × 策略。");

clearScene();setEq(null);
setBig("梯度里当然有转移概率","它就写在 P(τ;θ) 里面");
setCap("它确实写在里面 —— <b>但它不含 θ</b>。");

clearScene();setBig(null);
setEq("$$\\log P=\\underbrace{\\log\\mu(s_0)}_{\\text{no }\\theta}+\\underbrace{\\textstyle\\sum_t\\log P(s_{t+1}|s_t,a_t)}_{\\text{no }\\theta}+\\textstyle\\sum_t\\log\\pi_\\theta(a_t|s_t)$$","top");
note("前两项与 θ 无关",640,320,"g lg");
setCap("取 log 之后三项<b>相加</b>，而<b>前两项都不含 θ</b>。");

clearScene();setBig(null);
setEq("$$\\nabla_\\theta V=\\mathbb{E}\\Big[\\Big(\\textstyle\\sum_t\\nabla_\\theta\\log\\pi_\\theta(a_t|s_t)\\Big)R(\\tau)\\Big]$$","top");
note("模型不见了",640,300,"g lg");
note("只剩策略的导数",640,360,"g lg");
setCap("<b>转移概率整个消失了</b>。梯度里只剩下你自己那个可导的 π_θ。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"初始分布",sub:"不含 θ · 求导归零",state:"dead"},
  {label:"转移概率",sub:"不含 θ · 求导归零",state:"dead"},
  {label:"策略",sub:"只剩它",state:"on"}]});
note("不是假设掉的，是消掉的",640,420,"y");
setCap("<b>指名反驳</b>：模型<b>不是被假设掉的，是被求导消掉的</b>。");
